// Function to compare two arrays of objects
function compareData(data1, data2) {
  const discrepancies = [];

  // Check if the number of rows is the same
  if (data1.length !== data2.length) {
    discrepancies.push(`Number of rows differ: ${data1.length} vs ${data2.length}`);
  }

  // Compare each row
  for (let i = 0; i < Math.min(data1.length, data2.length); i++) {
    const row1 = data1[i];
    const row2 = data2[i];

    // Compare each field
    for (const key in row1) {
      if (row1[key] !== row2[key]) {
        discrepancies.push(`Discrepancy at row ${i + 1}, column "${key}": ${row1[key]} vs ${row2[key]}`);
      }
    }
  }

  return discrepancies;
}

